class EmailCopyPage extends ConsumerStatefulWidget{
 const EmailCopyPage({super.key});@override ConsumerState<EmailCopyPage> createState()=>_EmailCopyPageState();
}
class _EmailCopyPageState extends ConsumerState<EmailCopyPage>{
 final _raw=TextEditingController();String? _category;bool _subject=false,_sender=false,_date=false,_busy=false;IntegrationEmailPreview? _preview;int? _consentRevision;
 @override void dispose(){_raw.dispose();super.dispose();}
 Map<String,dynamic> get _input=>{'raw':_raw.text,'category':_category,'include_subject':_subject,'include_sender':_sender,'include_declared_date':_date};
 Future<void> _pick()async{try{final raw=await pickSelectedEmail();if(raw!=null&&mounted){setState((){_raw.text=raw;_preview=null;});}}catch(e){if(mounted){integrationSnack(context,'$e');}}}
 Future<void> _review()async{setState(()=>_busy=true);try{final repo=await ref.read(bootstrapProvider.future);final p=IntegrationEmailPreview.fromJson(repo.integrations('email_preview',_input) as Map<String,dynamic>);if(mounted){setState(()=>_preview=p);}}catch(e){if(mounted){integrationSnack(context,'$e');}}finally{if(mounted){setState(()=>_busy=false);}}}
 Future<void> _save()async{final preview=_preview;if(preview==null){return;}if(!await integrationConfirm(context,'Save only this reviewed email copy?','The exact displayed text enters the private library and normal local analysis. The original .eml, excluded headers and attachments are not saved. Header identity and dates are unverified.')){return;}if(!mounted){return;}setState(()=>_busy=true);try{final repo=await ref.read(bootstrapProvider.future);final item=repo.integrations('email_import',{..._input,'review_hash':preview.hash}) as Map<String,dynamic>;refreshIntegrationLibrary(ref);if(mounted){context.go('/reader/${item['id']}');}}catch(e){if(mounted){integrationSnack(context,'$e');}}finally{if(mounted){setState(()=>_busy=false);}}}
